#!/usr/bin/env python3
"""Worker: drain the durable queue into the result store."""
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import QUEUE, RESULTS, atomic_write, ensure_dirs

POLL_INTERVAL = 0.1


def process(name):
    qpath = os.path.join(QUEUE, name)
    try:
        with open(qpath, "rb") as f:
            data = f.read()
    except (FileNotFoundError, IsADirectoryError):
        return
    atomic_write(RESULTS, name, data)
    try:
        os.unlink(qpath)
    except FileNotFoundError:
        pass
    fd = os.open(QUEUE, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def main():
    ensure_dirs()
    while True:
        try:
            names = sorted(n for n in os.listdir(QUEUE) if not n.startswith(".tmp"))
            for name in names:
                try:
                    process(name)
                except Exception as e:
                    print("worker: error processing %s: %r" % (name, e), flush=True)
        except Exception as e:
            print("worker: scan error: %r" % (e), flush=True)
        time.sleep(POLL_INTERVAL)


if __name__ == "__main__":
    main()

